import "./DXVerticalNavigation.scss";
import React, { useState, useEffect } from "react";
import DXButton from "../DXButton";
import { LinksProps, getLinkTarget, StateIcons, getIcon } from "../../utilities";

export interface NavigationItem extends LinksProps {
    active?: boolean;
    items?: NavigationItem[];
    opened?: boolean;
}

export interface VerticalNavigationProps {
    items: NavigationItem[];
    icons?: StateIcons;
}

const DXVerticalNavigation = ( props: VerticalNavigationProps ) => {
    const [openedItems, setOpenedItems] = useState<any>( [] );

    const OPEN_ICON_DEFAULT = "ci-Caret_Down_MD";
    const CLOSE_ICON_DEFAULT = "ci-Caret_Up_MD";

    const openSubMenu = ( e: any, openIndex: string ) => {
        e.preventDefault();
        e.stopPropagation();
        if ( e.type === "click" || ( e.type === "keydown" && e.keyCode === 13 ) || ( e.type === "keydown" && e.keyCode === 32 ) ) {
            let target = e.target as HTMLElement;
            let test = target.closest( ".nav-item" );
            let submenu = test?.childNodes[1] as HTMLElement;
            if ( submenu.classList.contains( "show" ) ) {
                let filteredArray = openedItems.filter( ( item: string ) => item !== openIndex );
                setOpenedItems( [...filteredArray] );
            } else {
                setOpenedItems( [...openedItems, openIndex] );
            }
            submenu.classList.toggle( "show" );
        }
    };

    const openLink = ( e: any, url: string, target?: string ) => {
        e.stopPropagation();
        if ( e.type === "click" || ( e.type === "keydown" && e.keyCode === 13 ) || ( e.type === "keydown" && e.keyCode === 32 ) ) {
            window.open( url, getLinkTarget( target ) );
        }
    };

    const getItemIcon = ( openIndex: string ) => {
        if ( openedItems.includes( openIndex ) ) return getIcon( props.icons, "close", CLOSE_ICON_DEFAULT );
        return getIcon( props.icons, "open", OPEN_ICON_DEFAULT );
    };

    const saveOpenedItems = ( items: NavigationItem[], level: number ) => {
        items.map( ( item: NavigationItem, index: number ) => {
            if ( item.opened ) setOpenedItems( [...openedItems, `${level}-${index}`] );
            if ( item.items ) saveOpenedItems( item.items, level + 1 );
        } );
    };
    useEffect( () => {
        saveOpenedItems( props.items, 0 );
    }, [props.items] );

    const renderItems = ( items: any[], level: number ) => {
        return items.map( ( item: any, index: number ) => (
            <li className="nav-item" key={index}>
                {item.items ? (
                    <>
                        <div className="dxVerticalNav__triggerContainer">
                            <DXButton
                                label={item.label}
                                className={`collapse-icon btn nav-link ${item.active ? "active" : ""}`}
                                role="button"
                                onClick={( e: any ) => openLink( e, item.url, item.target )}
                                displayType="unstyled"
                                data-testid="vertical-nav-button"
                                key={`trigger-${index}`}
                            />
                            <DXButton
                                label="collapse-trigger"
                                hideLabel
                                data-testid="vertical-nav-button-icon"
                                onClick={( e: any ) => openSubMenu( e, `${level}-${index}` )}
                                icon={{ class: getItemIcon( `${level}-${index}` ) }}
                                displayType="unstyled" />
                        </div>
                        <div className={`collapse ${item.opened ? "show" : ""} ${level > 0 ? "sublevel" : ""}`} key={`collapse-${index}`}>
                            <ul className="nav nav-stacked">
                                {renderItems( item.items, level + 1 )}
                            </ul>
                        </div>
                    </>
                ) : (
                    <a href={item.url} className={`nav-link ${item.active ? "active" : ""}`}
                        target={getLinkTarget( item.target )}>{item.label}</a>
                )}
            </li>
        ) );
    };

    return (
        <div className="dxVerticalNav" data-testid="test">
            <ul className="nav nav-nested">
                {renderItems( props.items, 0 )}
            </ul>
        </div>
    );
};

export default DXVerticalNavigation;
